import cv2
for fn in ['/app/output/test_practice_cam.png','/app/target.png']:
 im=np.array(Image.open(fn).convert('RGB'))
 g=im.mean(2)
 mask=(g<100).astype('uint8')
 n,lab,stats,cents=cv2.connectedComponentsWithStats(mask,8)
 print('\n',fn,im.shape,'threshold pixels',int(mask.sum()))
 for s,c in sorted(zip(stats[1:],cents[1:]),key=lambda a:a[0][4],reverse=True)[:20]:
  if s[4]>10: print(' bbox',s[:4].tolist(),'area',int(s[4]),'center',np.round(c,1).tolist())
 if 'practice' in fn:
  # identify dark run width across columns at middle of each stroke's length
  for v in [512,500,480]:
   cols=np.where(mask[v]>0)[0]
   runs=[]
