import numpy as np
from scipy import ndimage
s=np.load('/app/output/target_skeleton.npy'); lab,n=ndimage.label(s,np.ones((3,3),bool))
for k in range(1,n+1):
 rc=np.argwhere(lab==k); S=set(map(tuple,rc)); adj={p:[] for p in S}
 for r,c in S:
  for dr,dc in [(0,1),(1,0)]:
   q=(r+dr,c+dc)
   if q in S: adj[(r,c)].append(q);adj[q].append((r,c))
 for r,c in S:
  for dr,dc in [(1,1),(1,-1)]:
   q=(r+dr,c+dc)
   if q not in S:continue
   if (r+dr,c) in S or (r,c+dc) in S:continue
   adj[(r,c)].append(q);adj[q].append((r,c))
 # cc count
 seen=set();cc=0
 for p in S:
  if p in seen:continue
  cc+=1;todo=[p];seen.add(p)
  while todo:
   a=todo.pop()
   for b in adj[a]:
    if b not in seen:seen.add(b);todo.append(b)
 deg=[len(v) for v in adj.values()]
 print(k,'nodes',len(S),'edges',sum(deg)//2,'odd',sum(d%2 for d in deg),'cc',cc,'deg3',deg.count(3),'ends',deg.count(1))
